'use strict';
let DATA,view='teach',chapter=0,session=null,storageOK=true;
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let progress={cards:{},xp:0,days:[]};try{let p=JSON.parse(localStorage.getItem('cis320-v1'));if(p&&p.cards&&typeof p.xp==='number'&&Array.isArray(p.days))progress=p}catch(e){storageOK=false}
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
const all=()=>[...DATA.questions,...VOCAB];const chosen=a=>chapter?a.filter(x=>x.ch===chapter):a;
const due=x=>!progress.cards[x.id]||progress.cards[x.id].due<=Date.now();const mastered=x=>(progress.cards[x.id]?.level||0)>=3;
function save(){try{localStorage.setItem('cis320-v1',JSON.stringify(progress))}catch(e){storageOK=false}}
function record(item,ok){const old=progress.cards[item.id]||{level:0,seen:0};const level=ok?(old.due>Date.now()?old.level:Math.min(6,old.level+1)):0;progress.cards[item.id]={level,seen:old.seen+1,firstCorrectAt:old.firstCorrectAt||(old.level>0?Date.now():ok?Date.now():null),due:ok&&old.due>Date.now()?old.due:Date.now()+(ok?[0,1,3,7,14,30,60][level]*86400000:60000)};progress.xp+=ok?10:2;const day=new Date().toLocaleDateString('en-CA');if(!progress.days.includes(day))progress.days.push(day);save();stats()}
function stats(){$('#stats').innerHTML=`<span>✦ ${progress.xp} XP</span><span>${progress.days.length} study day${progress.days.length===1?'':'s'}</span>`}
function chapterTitle(ch){const c=DATA.chapters.find(c=>c.id===ch);return c?`Chapter ${ch} · ${c.title}`:'All chapters'}
function picker(){return `<label class="tiny">Chapter <select id="chapter"><option value="0">All chapters</option>${DATA.chapters.map(c=>`<option value="${c.id}" ${chapter===c.id?'selected':''}>${c.id} · ${c.title}</option>`).join('')}</select></label>`}
function heading(title,desc){return `<div class="heading"><div><div class="eyebrow">CIS 320 / TEST 01</div><h1>${title}</h1><p class="muted">${desc}</p></div>${picker()}</div>`}
const navs=[['teach','☀','Learn First'],['decoder','▦','Subnet decoder'],['learn','◈','Learn'],['notes','☀','Easy explanations'],['understanding','◎','Check understanding'],['flash','▤','Flashcards'],['terms','Aa','Terms & definitions'],['abbrev','⌁','Abbreviations'],['sort','≋','Put it in order'],['numbers','#','Numbers lab'],['exam','✓','Practice exam'],['guide','☷','Full study guide']];
function navigate(v){view=v;session=null;render();window.scrollTo(0,0)}
function render(){stats();renderModeBar();$('#nav').innerHTML=navs.map(([v,i,t])=>`<button class="${view===v?'active':''}" data-nav="${v}">${i} &nbsp; ${t}</button>`).join('');let app=$('#app');if(session){renderSession();return}if(view==='teach')teachHome();if(view==='decoder')decoderHome();if(view==='learn')learn();if(view==='notes')notesHome();if(view==='understanding')understandingHome();if(view==='flash')flashHome();if(view==='terms')terms();if(view==='abbrev')abbrevHome();if(view==='sort')sortHome();if(view==='numbers')numbersHome();if(view==='exam')examHome();if(view==='guide')guide();let c=$('#chapter');if(c)c.onchange=()=>{chapter=+c.value;render()}}
function learn(){let pool=chosen(learnPool()),m=pool.filter(completedOnce).length,d=pool.filter(due).length;$('#app').innerHTML=heading('A little practice. A stronger memory.','Chapter practice mixes guide questions, terms, abbreviations, sorting and number drills. Missed items return until you answer them correctly.')+`<section class="focus"><div><div class="eyebrow" style="color:#b8d8be">TODAY’S SESSION</div><h2>${d?'Your next 10 questions':'Keep your knowledge fresh'}</h2><p>${d} items ready for review · ${chapterTitle(chapter)}</p><button class="primary" id="daily">Start practice &nbsp; →</button></div><div class="ring">${Math.round(100*m/pool.length)}%<small>COMPLETED</small></div></section><div class="heading"><h2>Your chapters</h2><span class="tiny muted">${DATA.questions.length} guide prompts · mixed chapter practice</span></div><div class="grid">${DATA.chapters.map(c=>{let p=learnPool().filter(x=>x.ch===c.id),n=p.filter(completedOnce).length;return `<article class="card chapter"><div class="badge">${c.id}</div><div><div class="eyebrow">CHAPTER ${c.id}</div><h3>${c.title}</h3><p class="muted">${DATA.questions.filter(x=>x.ch===c.id).length} guide prompts · ${learnPool().filter(x=>x.ch===c.id&&!x.id.startsWith('q')).length} related exercises</p><div class="bar"><span style="width:${100*n/p.length}%"></span></div><div class="tiny muted" style="margin-top:8px">${n} / ${p.length} completed once${n===p.length?' · ✓ Chapter complete':''}</div><button data-chstart="${c.id}">Practice full chapter &nbsp; →</button><button data-ch-notes="${c.id}">Read easy explanations</button></div></article>`}).join('')}</div><div class="notice">The completion bar fills when each item has been answered correctly once. Retention is tracked separately: 3 successful scheduled reviews. Correct answers return after 1, 3, then 7 days; missed items return sooner. Self-rated recall counts too, so mark honestly. No mastery estimate guarantees exam performance.</div><footer>${storageOK?'Progress is saved on this browser only.':'Browser storage is unavailable; progress will not be saved after you leave.'} Review sessions prioritize due and missed items. All chapters are available from the start.</footer>`;document.querySelectorAll('[data-ch-notes]').forEach(b=>b.onclick=()=>{chapter=+b.dataset.chNotes;navigate('notes')});$('#daily').onclick=()=>start('mixed',mixedReview(pool));document.querySelectorAll('[data-chstart]').forEach(b=>b.onclick=()=>{chapter=+b.dataset.chstart;start('mixed',shuffle(chosen(learnPool())))})}
function reviewPool(pool){const rank=x=>{let p=progress.cards[x.id];if(p&&p.level===0)return 0;if(p&&due(x))return 1;if(!p)return 2;return 3};return shuffle(pool).sort((a,b)=>rank(a)-rank(b)).slice(0,10)}
function flashHome(){$('#app').innerHTML=heading('Flip it. Recall it.','Say the answer before you reveal it. Then rate your recall.')+`<div class="grid"><section class="card"><h2>Study-guide flashcards</h2><p>Every original question, with a complete answer. ${chosen(DATA.questions).length} cards in this selection.</p><button class="primary" id="guideflash">Study questions</button></section><section class="card"><h2>Vocabulary flashcards</h2><p>Build a precise definition for every term. ${chosen(VOCAB).length} cards in this selection.</p><button class="primary" id="termflash">Study terms</button></section></div><div class="actions"><button id="dueflash">Review due cards (${chosen(all()).filter(due).length})</button></div>`;$('#guideflash').onclick=()=>start('flash',shuffle(chosen(DATA.questions)));$('#termflash').onclick=()=>start('flash',shuffle(chosen(VOCAB)));$('#dueflash').onclick=()=>start('flash',shuffle(chosen(all()).filter(due)))}
function terms(){$('#app').innerHTML=heading('Every term, understood.','A complete dictionary, with extra vocabulary to fill in the gaps.')+`<label>Find a term <input id="search" placeholder="Try: frame, CIDR, multiplexing…" type="search"></label><div id="terms" class="wordlist"></div>`;const update=()=>{let q=$('#search').value.toLowerCase();let terms=chosen(VOCAB).filter(x=>(x.term+' '+x.a+' '+x.exp).toLowerCase().includes(q));$('#terms').innerHTML=terms.length?terms.map(x=>`<article><span class="tag">Chapter ${x.ch}</span><h3>${esc(x.term)}${x.exp?' · '+esc(x.exp):''}</h3><div class="explanation">${readableText(x.a)}</div></article>`).join(''):'<p>No matching terms.</p>'};$('#search').oninput=update;update()}
function abbrevHome(){let list=chosen(VOCAB).filter(x=>x.exp);$('#app').innerHTML=heading('What does it stand for?','Choose the full name, then learn what it means.')+`<section class="card"><h2>${list.length} abbreviations to know</h2><p>${list.map(x=>esc(x.term)).join(' · ')}</p><div class="actions"><button class="primary" id="abbrevstart">What does it stand for?</button><button id="abbrevbuild">Build names with a word bank</button><button id="abbrevblank">Fill in the blanks</button></div><p class="tiny muted">Tap an answer. Every choice is followed by an explanation.</p></section>`;$('#abbrevstart').onclick=()=>start('abbrev',shuffle(list));$('#abbrevbuild').onclick=()=>start('abbrev',shuffle(wordBankCards(list)));$('#abbrevblank').onclick=()=>start('abbrev',shuffle(chosen(clozeCards().filter(x=>x.abbrev))))}
function guide(){$('#app').innerHTML=heading('Your complete study guide','All 54 original prompts, organized by chapter. Expand any prompt to study its answer.')+`<div class="notice">Original prompt wording is preserved, including embedded notes. Answers marked “Clarified / supplemented” resolve errors or incomplete details in the document. The course uses the five-layer TCP/IP teaching model. Extra vocabulary is supplemental.</div>`+chosen(DATA.questions).map(x=>`<article class="card" style="margin-top:14px"><span class="tag">${chapterTitle(x.ch)}</span><details><summary>${esc(x.q)}</summary><div class="explanation">${readableText(x.a)}</div><span class="tag">${x.note}</span></details></article>`).join('')+`<footer>Technical references: <a href="https://www.cisco.com/en/US/docs/internetworking/troubleshooting/guide/tr1904.html" target="_blank" rel="noreferrer">Ethernet / duplex</a> · <a href="https://www.rfc-editor.org/rfc/rfc4291" target="_blank" rel="noreferrer">IPv6 addressing</a> · <a href="https://www.rfc-editor.org/rfc/rfc3021" target="_blank" rel="noreferrer">/31 point-to-point addressing</a>. <a href="https://www.flukenetworks.com/knowledge-base/applicationstandards-articles-copper/category-8-cabling-fact-sheet" target="_blank" rel="noreferrer">Cat 8 cabling</a> · <a href="https://www.cisco.com/c/en/us/products/collateral/interfaces-modules/transceiver-modules/data_sheet_c78-455693.html" target="_blank" rel="noreferrer">Fiber reach examples</a>. Exact fiber reach and cable performance depend on the installed standard and equipment.</footer>`}
function makeMC(item){if(item.options&&item.answer)return {...item,options:shuffle(item.options)};let answer=item.quizAnswer||item.exp||item.a;let distractors=item.distractors||DATA.vocabDistractors[item.term];if(!distractors||distractors.length!==3)throw Error('Missing authored choices for '+item.id);return {...item,q:item.exp?`What does ${item.term} stand for?`:(item.practiceQ||item.q),answer,options:shuffle([answer,...distractors])}}
function examHome(){$('#app').innerHTML=heading('Make exam day feel familiar.','Generate a fresh multiple-choice exam. Get an explanation after every answer and a score at the end.')+`<section class="card"><h2>Build your exam</h2><div class="row"><label>Question bank<br><select id="bank"><option value="all">Guide + vocabulary</option><option value="guide">All guide prompts</option><option value="terms">Vocabulary</option></select></label><label>Length<br><select id="length"><option value="10">10 questions</option><option value="20" selected>20 questions</option><option value="40">40 questions</option><option value="9999">Entire selected bank</option></select></label></div><p class="muted">Questions and choices are shuffled each time. No timer. Your first choice is scored. You can revisit explanations before submitting.</p><button class="primary" id="examstart">Generate exam &nbsp; →</button></section>`;$('#examstart').onclick=()=>{let bank=$('#bank').value;let pool=chosen(bank==='guide'?DATA.questions:bank==='terms'?VOCAB:all());start('exam',shuffle(pool).slice(0,+$('#length').value).map(makeMC))}}
function start(mode,items){items=items.map(x=>x.kind==='wordbank'?prepareWordBank(x):x.kind==='sort'?({...x,current:shuffledOrder(x.items)}):mode==='flash'?({...x,q:x.practiceQ||x.q}):makeMC(x));session={mode,items,index:0,right:0,missed:[],answers:{},total:items.length,cleared:new Set(),attempts:0,revealed:false,graded:false};renderSession()}
function readableText(value){
  const lines=String(value||'').split(/\n+/).map(t=>t.trim()).filter(Boolean);
  return lines.map(line=>{const sentences=line.split(/(?<=[.!?])\s+(?=[A-Z])/);return sentences.map(t=>`<p>${esc(t.trim())}</p>`).join('')}).join('');
}
const TERM_REASONS={
 'Network layer':'The Network layer uses the destination IP address to decide where a packet should go. Routing moves that packet between networks. That is why logical IP addressing and routing belong to this layer.',
 'Application layer':'The Application layer provides the network services an application uses to communicate. This is the layer closest to the user’s application.',
 'Transport layer':'The Transport layer handles communication between application processes on the end devices. Its scope is end to end, rather than just one local link.',
 'Data Link layer':'The Data Link layer transfers frames across a local link. It uses MAC addresses to identify interfaces for local delivery.',
 'Physical layer':'Bits are 0s and 1s. To cross a cable or travel through the air, they must be represented by a real signal. The Physical layer sends and receives those signals.\nFor example: copper carries electrical signals, optical fiber carries light, and Wi-Fi uses radio waves.\nThat is why transmitting signals is the correct answer. Choosing an IP route is the Network layer’s job; handling local frames and MAC addresses is the Data Link layer’s job.',
 'Presentation layer':'The OSI Presentation layer handles how data is represented. Formatting, encryption and compression change that representation, so they belong to this layer.',
 'Session layer':'The OSI Session layer manages the communication session. Starting, maintaining and ending that session are its responsibilities.'
};
function noteInline(text){return esc(text).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<b>$1</b>').replace(/\*([^*]+)\*/g,'<em>$1</em>')}
function noteMarkdown(body){
 const lines=body.split('\n');let out='',paragraph=[];
 const flush=()=>{if(paragraph.length){out+='<p>'+noteInline(paragraph.join(' '))+'</p>';paragraph=[]}};
 for(let i=0;i<lines.length;i++){
  const line=lines[i].trim();
  if(!line||line==='---'){flush();continue}
  if(line.startsWith('```')){flush();let code=[];while(++i<lines.length&&!lines[i].trim().startsWith('```'))code.push(lines[i]);out+='<pre>'+esc(code.join('\n'))+'</pre>';continue}
  if(line.startsWith('|')){flush();let rows=[];while(i<lines.length&&lines[i].trim().startsWith('|')){let cells=lines[i].trim().slice(1,-1).split('|').map(x=>x.trim());if(!cells.every(x=>/^:?-+:?$/.test(x)))rows.push(cells);i++}i--;out+='<div class="note-table"><table><thead><tr>'+rows[0].map(c=>'<th>'+noteInline(c)+'</th>').join('')+'</tr></thead><tbody>'+rows.slice(1).map(r=>'<tr>'+r.map(c=>'<td>'+noteInline(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';continue}
  if(/^#+ /.test(line)){flush();out+='<h3>'+noteInline(line.replace(/^#+ /,''))+'</h3>';continue}
  if(/^(?:[*-]|\d+\.) /.test(line)){flush();let items=[];while(i<lines.length&&/^(?:[*-]|\d+\.) /.test(lines[i].trim())){items.push(lines[i].trim().replace(/^(?:[*-]|\d+\.) /,''));i++}i--;out+='<ul>'+items.map(x=>'<li>'+noteInline(x)+'</li>').join('')+'</ul>';continue}
  paragraph.push(line);
 }
 flush();return out;
}
function lessonBody(n){return `<div class="remember">${readableText(n.remember)}</div><div class="note-body">${noteMarkdown(n.body)}</div>${n.sources.length?'<p class="tiny">References: '+n.sources.map(r=>`<a href="${esc(r.url)}" target="_blank" rel="noreferrer">${esc(r.title)}</a>`).join(' · ')+'</p>':''}`}
function openLesson(id){const n=DATA.notes.find(n=>n.id===id);if(!n)return;let panel=document.createElement('dialog');panel.className='lesson-dialog';panel.innerHTML=`<button class="close-lesson">Close explanation</button><span class="tag">${chapterTitle(n.ch)}</span><h2>${esc(n.title)}</h2>${lessonBody(n)}`;document.body.append(panel);panel.querySelector('.close-lesson').onclick=()=>panel.close();panel.onclose=()=>panel.remove();panel.showModal()}
function notesHome(){const list=chosen(DATA.notes),questions=chosen(DATA.notesQuestions);$('#app').innerHTML=heading('Easy explanations','Your added notes, broken into smaller ideas. Read a topic, then try a question.')+`<div class="notice">These notes include extra details from your new material. Added-notes practice stays separate from the original guide and exam bank; extra details are not confirmed exam requirements.</div><div class="actions"><button class="primary" id="notes-practice">Practice added notes (${questions.length})</button></div><div class="notes-list">${list.map(n=>`<article class="card"><span class="tag">${chapterTitle(n.ch)}</span><details><summary>${esc(n.title)}</summary>${lessonBody(n)}${questions.some(q=>q.lessonId===n.id)?`<button data-note-practice="${n.id}" class="primary">Practice this topic</button>`:''}</details></article>`).join('')}</div>`;$('#notes-practice').onclick=()=>start('notes',shuffle(questions));document.querySelectorAll('[data-note-practice]').forEach(b=>b.onclick=()=>start('notes',shuffle(DATA.notesQuestions.filter(q=>q.lessonId===b.dataset.notePractice))))}
function beginnerReminder(x){if(['Working group','RIR','End-user','Allocation','Public IP','Core layer'].includes(x.term))return 'Remember: '+JARGON[x.term];
 if(x.remember)return x.remember;
 if(x.sourceId){const source=DATA.questions.find(q=>q.id===x.sourceId);if(source?.remember)return source.remember}
 if(TERM_REASONS[x.term])return 'Remember: '+TERM_REASONS[x.term];
 if(x.term)return `Remember: ${x.term}${x.exp?' stands for '+x.exp:''}. ${x.a}`;
 return 'Remember: '+(x.explain||x.a||'Work through the correct answer one piece at a time.');
}
function explanationHTML(x,selected){
  const correct=x.answer||x.exp||x.a,ok=selected===correct;
  const why=x.explain||TERM_REASONS[x.term]||(x.term?`${x.term}${x.exp?' ('+x.exp+')':''}: ${x.a}`:x.a);
  const related=x.term&&!x.explain?DATA.vocabExplanations[x.term]:null;
  return `<div class="feedback" role="status"><p class="tiny">${esc(questionContext(x))}</p><strong>${selected===undefined?'Answer explained':ok?'✓ Correct':'Not quite — review the answer'}</strong>${selected!==undefined?`<div class="correct-answer"><h3>Correct answer</h3>${readableText(correct)}</div>`:''}${selected!==undefined&&!ok?`<div class="remember"><h3>Let’s make it simple</h3>${readableText(beginnerReminder(x))}</div>`:''}${selected!==undefined&&!ok?'<details><summary>More detail</summary>':''}<div class="explanation"><h3>${x.term&&!x.explain&&!TERM_REASONS[x.term]?'What it means':'Why this is correct'}</h3>${readableText(why)}</div>${selected!==undefined&&!ok?'</details>':''}${related&&related!==why?`<details><summary>Related concepts from this topic</summary>${readableText(related)}</details>`:''}${TERM_REASONS[x.term]?'<details><summary>Reference for this explanation</summary><p><a href="https://learn.microsoft.com/en-us/windows-hardware/drivers/network/windows-network-architecture-and-the-osi-model" target="_blank" rel="noreferrer">Microsoft: OSI layer responsibilities</a> · <a href="https://www.ibm.com/think/topics/osi-model" target="_blank" rel="noreferrer">IBM: the OSI model</a></p></details>':''}${x.lessonId?`<button class="lesson-link" data-lesson="${esc(x.lessonId)}">Read the easy explanation</button>`:''}${x.sourceId?`<details><summary>Study-guide topic behind this question</summary><p>${esc(DATA.questions.find(q=>q.id===x.sourceId)?.q||'')}</p></details>`:''}</div>`;
}
function sessionStatus(s){return `${s.cleared.size} / ${s.total} learned${s.items[s.index]?.retry?' · Try again':''}`}
function retryNotice(ok){return ok?'':'<p class="retry-note">This will come back for another try before you finish.</p>'}
function renderSession(){renderModeBar();let s=session;if(!s.items.length){$('#app').innerHTML='<section class="card empty"><h2>You’re caught up.</h2><p>No items in this selection need review right now.</p><button id="back">Back to study</button></section>';$('#back').onclick=()=>navigate(view);return}if(s.index>=s.items.length){finish();return}if(s.mode==='exam'){renderExam();return}let x=s.items[s.index],flash=s.mode==='flash';if(x.kind==='wordbank'){renderWordBank(x);return}if(x.kind==='sort'){renderMixedSort(x);return}$('#app').innerHTML=`<div class="study"><div class="row spread"><button id="exit">← Exit session</button><span class="muted">${sessionStatus(s)}</span></div><div class="bar" style="margin:24px 0"><span style="width:${100*s.cleared.size/s.total}%"></span></div><span class="tag">${questionContext(x)}</span>${preTeachHTML(x)}<section class="card" style="margin-top:16px"><div class="eyebrow">${flash?'RECALL BEFORE REVEAL':x.kind==='number'?'DECODE THE HIGHLIGHT':x.kind==='understanding'?'CHECK YOUR UNDERSTANDING':x.exp?'ABBREVIATION':'CHOOSE ONE ANSWER'}</div><h2 class="question">${esc(x.q)}</h2>${x.display?`<div class="number">${x.display}</div>`:''}${flash?'<div class="actions"><button class="primary" id="reveal">Reveal answer & explanation</button></div>':`<div class="choices">${x.options.map((a,i)=>`<button data-answer="${i}">${String.fromCharCode(65+i)}. ${esc(a)}</button>`).join('')}</div>`}<div id="revealarea"></div></section><p class="tiny muted">${x.note||'Supplemental vocabulary'} · ${flash?'Think of your answer, then reveal it.':'Tap a choice. We’ll explain the answer before moving on.'}</p></div>`;$('#exit').onclick=()=>navigate(view);if(flash){$('#reveal').onclick=()=>{if(s.revealed)return;s.revealed=true;$('#reveal').disabled=true;$('#revealarea').innerHTML=`<div class="answer">${readableText(x.exp||x.a)}</div>${explanationHTML(x)}<div class="actions"><button id="no">Not yet</button><button class="primary" id="yes">I recalled it</button></div>`;$('#no').onclick=()=>advance(false);$('#yes').onclick=()=>advance(true)}}else{document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(s.revealed)return;s.revealed=true;let selected=x.options[+b.dataset.answer],ok=selected===x.answer;document.querySelectorAll('[data-answer]').forEach(v=>{v.disabled=true;let a=x.options[+v.dataset.answer];if(a===x.answer)v.classList.add('correct');else if(v===b)v.classList.add('wrong')});$('#revealarea').innerHTML=explanationHTML(x,selected)+retryNotice(ok)+'<button id="continue" class="primary">Continue →</button>';$('#continue').onclick=()=>advance(ok)})}}
function advance(ok){
 const s=session,x=s.items[s.index];
 record(x,ok);s.attempts++;
 if(ok){s.right++;s.cleared.add(x.id)}else{
   if(!s.missed.some(item=>item.id===x.id))s.missed.push(x);
   const retry={...x,retry:true};
   if(x.kind==='wordbank')Object.assign(retry,prepareWordBank(x));
   else if(x.kind==='sort')retry.current=shuffledOrder(x.items);
   else if(x.options)retry.options=shuffle(x.options);
   s.items.splice(Math.min(s.index+4,s.items.length),0,retry);
 }
 s.index++;s.revealed=false;s.graded=false;renderSession();window.scrollTo(0,0);
}
function finish(){let s=session;if(s.mode!=='exam'){if(s.lessonId){progress.lessons=progress.lessons||{};progress.lessons[s.lessonId]=Date.now();save()}$('#app').innerHTML=`<section class="card study empty"><span class="tag">PRACTICE COMPLETE</span><h1>Every item answered correctly.</h1><div class="count">${s.cleared.size} / ${s.total}</div><p>${s.total} items learned in ${s.attempts} attempts.</p><p>${s.missed.length?`${s.missed.length} items needed another try. You worked through all of them.`:'You got every item on your first try.'}</p><p class="muted">Come back for scheduled reviews to keep them fresh.</p><button id="done" class="primary">Back to study</button>${s.mode==='subnet'?'<button id="another-subnet">Generate another practice subnet</button>':''}</section>`;$('#done').onclick=()=>navigate(view);if($('#another-subnet'))$('#another-subnet').onclick=()=>start('subnet',subnetQuestions(dissectCIDR(randomSubnet())));return}$('#app').innerHTML=`<section class="card study empty"><span class="tag">SESSION COMPLETE</span><h1>${s.missed.length?'Good work. Let’s strengthen the gaps.':'Practice complete.'}</h1><div class="count">${s.right} / ${s.items.length}</div><p>${s.mode==='flash'?'Recalled successfully':'Correct answers'} · ${s.missed.length} to revisit</p><div class="actions" style="justify-content:center">${s.missed.length?'<button class="primary" id="retry">Practice missed items</button>':''}<button id="done">Back to study</button></div></section>${s.mode==='exam'?'<div class="wordlist">'+s.items.map((x,i)=>`<article><span class="tag">${chapterTitle(x.ch)}</span><h3>${esc(x.q)}</h3><p>Your answer: ${esc(s.answers[i]||'Unanswered')}</p>${explanationHTML(x,s.answers[i])}</article>`).join('')+'</div>':''}`;if($('#retry'))$('#retry').onclick=()=>start(s.mode==='exam'?'recall':s.mode,shuffle(s.missed));$('#done').onclick=()=>navigate(view)}
function renderExam(){let s=session,x=s.items[s.index],selected=s.answers[s.index],answered=selected!==undefined;$('#app').innerHTML=`<div class="study"><div class="row spread"><button id="exit">← Exit exam</button><span>${Object.keys(s.answers).length} / ${s.items.length} answered</span></div><div class="bar" style="margin:24px 0"><span style="width:${100*Object.keys(s.answers).length/s.items.length}%"></span></div><span class="tag">${questionContext(x)}</span>${preTeachHTML(x)}<section class="card" style="margin-top:16px"><div class="eyebrow">QUESTION ${s.index+1} OF ${s.items.length}</div><h2 class="question">${esc(x.q)}</h2><div class="choices">${x.options.map((a,i)=>`<button data-opt="${i}" ${answered?'disabled':''} aria-pressed="${selected===a}" class="${answered?(a===x.answer?'correct':a===selected?'wrong':''):''}">${String.fromCharCode(65+i)}. ${esc(a)}</button>`).join('')}</div>${answered?explanationHTML(x,selected):''}<div class="row spread"><button id="prev" ${s.index===0?'disabled':''}>← Previous</button><button id="next" ${s.index===s.items.length-1||!answered?'disabled':''}>Next →</button></div></section><div class="actions"><button class="primary" id="submit" ${Object.keys(s.answers).length<s.items.length?'disabled':''}>See exam results</button><span class="tiny muted">Your first answer counts. Read the explanation before continuing.</span></div></div>`;$('#exit').onclick=()=>navigate('exam');document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{if(s.answers[s.index]!==undefined)return;s.answers[s.index]=x.options[+b.dataset.opt];renderExam()});$('#prev').onclick=()=>{s.index--;renderExam()};$('#next').onclick=()=>{s.index++;renderExam()};$('#submit').onclick=()=>{s.items.forEach((x,i)=>{let ok=s.answers[i]===x.answer;record(x,ok);if(ok)s.right++;else s.missed.push(x)});s.index=s.items.length;finish()}}
const ORDERS=[{id:'osi',ch:1,title:'OSI model',instruction:'Top → bottom (layer 7 to layer 1)',items:['Application','Presentation','Session','Transport','Network','Data Link','Physical']},{id:'tcpip',ch:1,title:'TCP/IP stack',instruction:'Top → bottom, using your guide’s five-layer model',items:['Application','Transport','Network / IP','Data Link','Physical']},{id:'encap',ch:1,title:'Encapsulation',instruction:'Sending host: application data down to the wire',items:['Application data','Transport segment','Network packet','Data-link frame','Physical bits / signals']},{id:'csma',ch:3,title:'CSMA/CD collision recovery',instruction:'Assume an idle shared medium, then a collision',items:['Sense the medium','Transmit if idle','Detect collision','Send jam signal and stop','Wait random backoff','Retry sensing and transmission']},{id:'frame',ch:3,title:'Ethernet on the wire',instruction:'Transmission order, including preamble and trailer',items:['Preamble','Start Frame Delimiter','Destination MAC','Source MAC','Length / Type','Data and padding','Frame Check Sequence']},{id:'campus',ch:12,title:'Campus hierarchy',instruction:'Backbone → end-user connectivity',items:['Core','Distribution','Access']},{id:'design',ch:12,title:'Network design process',instruction:'From understanding needs to ongoing operation',items:['Requirements analysis','Logical design','Physical design','Implementation and testing','Maintenance and monitoring']}];

function layerJobCards(){
 const jobs=[['Application','Provides network services to user applications.'],['Presentation','Formats, encrypts or compresses data in the OSI model.'],['Session','Starts, manages and ends communication sessions in the OSI model.'],['Transport','Provides end-to-end communication between application processes.'],['Network','Uses logical IP addresses and routes packets between networks.'],['Data Link','Transfers frames locally using MAC addresses.'],['Physical','Transmits raw bits as electrical, light or radio signals.']];
 return jobs.map(([answer,job],i)=>({id:'layer-job-'+i,ch:1,q:job+' Which layer does this?',answer,options:[answer,...jobs.filter(j=>j[0]!==answer).slice(0,3).map(j=>j[0])],explain:TERM_REASONS[answer+' layer'],sourceId:'q29'}));
}
let orderState=null;

let modelBuild=null;
const MODEL_KEYS=['osi','tcpip'];
const modelLayers=key=>ORDERS.find(o=>o.id===key).items;
function startModels(){modelBuild={slots:{osi:Array(7).fill(null),tcpip:Array(5).fill(null)},banks:{osi:shuffledOrder(modelLayers('osi')),tcpip:shuffledOrder(modelLayers('osi').map(x=>x==='Network'?'Network / IP':x))},checked:false};renderModels()}
function modelIsCorrect(key){return modelBuild.slots[key].every((v,i)=>v===modelLayers(key)[i])}
function renderModels(){
 const m=modelBuild,complete=MODEL_KEYS.every(key=>m.slots[key].every(Boolean)),passed=m.checked&&MODEL_KEYS.every(modelIsCorrect);
 $('#app').innerHTML=`<div class="study"><button id="models-back">← All sequences</button><span class="tag">Chapter 1</span><h1>Build OSI vs. TCP/IP</h1><p>Tap a layer to fill the next empty position, starting at the top. Tap a filled position to remove it.</p><p class="muted">Use your study guide’s <b>five-layer TCP/IP model</b>. Two names in its bank do not belong as separate layers.</p><div class="model-grid">${MODEL_KEYS.map(key=>`<section class="card"><h2>${key==='osi'?'OSI · 7 layers':'TCP/IP · 5 layers'}</h2><ol class="model-slots">${m.slots[key].map((v,i)=>`<li><button data-slot="${key}" data-position="${i}" ${m.checked?'disabled':''} class="${m.checked?(v===modelLayers(key)[i]?'correct':'wrong'):''}" aria-label="${key==='osi'?'OSI':'TCP/IP'} position ${i+1} from top${v?', remove '+esc(v):', empty'}"><span>${m.slots[key].length-i}</span>${v?esc(v):'Choose a layer'}</button></li>`).join('')}</ol><div class="model-bank">${m.banks[key].map((v,i)=>`<button data-model="${key}" data-layer="${i}" ${m.checked||m.slots[key].includes(v)||m.slots[key].every(Boolean)?'disabled':''}>${esc(v)}</button>`).join('')}</div></section>`).join('')}</div><div class="actions"><button id="models-check" class="primary" ${!complete||m.checked?'disabled':''}>Check both models</button><button id="models-reset">Start over</button></div>${m.checked?`<div class="feedback" role="status"><strong>${passed?'✓ Both models are correct':'Some layers need another try'}</strong><h3>The difference to remember</h3><p>OSI separates <b>Application, Presentation and Session</b>. In the TCP/IP model used in your guide, those responsibilities are grouped under <b>Application</b>.</p><p>Both stacks then have <b>Transport → Network → Data Link → Physical</b>.</p><details><summary>See the correct stacks</summary>${MODEL_KEYS.map(key=>`<h3>${key==='osi'?'OSI':'TCP/IP (course model)'}</h3><ol>${modelLayers(key).map(v=>`<li>${esc(v)}</li>`).join('')}</ol>`).join('')}</details><details><summary>Why some references show four TCP/IP layers</summary><p>The four-layer version groups Data Link and Physical into one Link or Network Access layer. Your guide separates them, so this exercise uses five.</p><a href="https://www.ibm.com/think/topics/osi-model" target="_blank" rel="noreferrer">Reference: IBM’s OSI and TCP/IP comparison</a></details><button id="models-again" class="primary">${passed?'Build again from memory':'Try both again'}</button></div>`:''}</div>`;
 $('#models-back').onclick=()=>navigate('sort');$('#models-reset').onclick=startModels;
 document.querySelectorAll('[data-model]').forEach(b=>b.onclick=()=>{const key=b.dataset.model,i=m.slots[key].indexOf(null);if(!m.checked&&i>=0){m.slots[key][i]=m.banks[key][+b.dataset.layer];renderModels()}});
 document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>{if(!m.checked){m.slots[b.dataset.slot][+b.dataset.position]=null;renderModels()}});
 $('#models-check').onclick=()=>{if(!complete||m.checked)return;m.checked=true;MODEL_KEYS.forEach(key=>record({id:'sort-'+key},modelIsCorrect(key)));renderModels()};
 if($('#models-again'))$('#models-again').onclick=startModels;
}
function sortHome(){$('#app').innerHTML=heading('Put the pieces in place.','Practice sequences until you can rebuild them from memory.')+`${!chapter||chapter===1?'<section class="card" style="margin-bottom:20px"><span class="tag">Chapter 1</span><h3>Build OSI vs. TCP/IP</h3><p>Build both stacks from memory and compare their layers.</p><button id="build-models" class="primary">Build both models</button></section><section class="card" style="margin-bottom:20px"><span class="tag">Chapter 1</span><h3>Match each layer to its job</h3><p>Choose the layer responsible for each networking task.</p><button id="match-layers" class="primary">Practice layer jobs</button></section>':''}<div class="grid">${chosen(ORDERS).map(o=>`<section class="card"><span class="tag">Chapter ${o.ch}</span><h3>${o.title}</h3><p class="muted">${o.instruction}</p><button data-order="${o.id}" class="primary">Sort ${o.items.length} steps</button></section>`).join('')}</div>`;if($('#build-models'))$('#build-models').onclick=startModels;if($('#match-layers'))$('#match-layers').onclick=()=>start('recall',shuffle(layerJobCards()));document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{let o=ORDERS.find(o=>o.id===b.dataset.order);orderState={...o,current:shuffledOrder(o.items),checked:false};renderOrder()})}
function renderOrder(){let o=orderState;$('#app').innerHTML=`<div class="study"><button id="backsort">← All sequences</button><h1>${o.title}</h1><p>${o.instruction}</p><span class="tag">${chapterTitle(o.ch)} · Sequencing</span>${preTeachHTML({...o,id:'sort-'+o.id,kind:'sort'})}<div class="order">${o.current.map((t,i)=>`<div><strong>${i+1}</strong><span>${t}</span><button data-up="${i}" aria-label="Move ${t} up" ${i===0?'disabled':''}>↑</button><button data-down="${i}" aria-label="Move ${t} down" ${i===o.current.length-1?'disabled':''}>↓</button></div>`).join('')}</div><p class="tiny muted">Use the arrows to move each item. Keyboard and touch supported.</p><button id="checkorder" class="primary">Check order</button><div id="orderfeedback" aria-live="polite"></div></div>`;$('#backsort').onclick=()=>navigate('sort');for(let dir of ['up','down'])document.querySelectorAll(`[data-${dir}]`).forEach(b=>b.onclick=()=>{let i=+b.dataset[dir],j=i+(dir==='up'?-1:1);[o.current[i],o.current[j]]=[o.current[j],o.current[i]];renderOrder()});$('#checkorder').onclick=()=>{let n=o.current.filter((x,i)=>x===o.items[i]).length;if(!o.checked){record({id:'sort-'+o.id},n===o.items.length);o.checked=true}$('#orderfeedback').innerHTML=`<div class="feedback">${n===o.items.length?'✓ Perfect order.':`${n} of ${o.items.length} positions are correct. Keep adjusting, or reveal the order.`}<div class="explanation">${readableText((n===o.items.length?'':'Remember: ')+ORDER_EXPLANATIONS[o.id])}</div></div>${n<o.items.length?'<button id="showorder">Reveal correct order</button>':''}<button id="reshuffle">Shuffle and try again</button>`;if($('#showorder'))$('#showorder').onclick=()=>{$('#orderfeedback').insertAdjacentHTML('beforeend',`<div class="answer">${o.items.join(' → ')}</div>`);$('#showorder').disabled=true};$('#reshuffle').onclick=()=>{o.current=shuffledOrder(o.items);o.checked=false;renderOrder()}}}
let lab=null;
function labItems(){return [
{id:'cidr-prefix',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'What does the highlighted prefix mean?',answer:'17 network bits',options:['17 network bits','17 host bits','17 network bytes','15 network bits'],explain:'IPv4 has 32 bits. /17 uses 17 for the network and leaves 15 host bits.'},
{id:'cidr-host',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'How many host bits remain?',answer:'15',options:['17','15','32','16'],explain:'32 − 17 = 15 host bits.'},
{id:'cidr-total',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'How many total addresses are in the block?',answer:'32,768',options:['32,768','32,766','65,536','131,072'],explain:'2^(32 − 17) = 2^15 = 32,768 total addresses.'},
{id:'cidr-usable',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'How many traditionally usable host addresses?',answer:'32,766',options:['32,766','32,768','65,534','131,070'],explain:'Subtract the network and broadcast addresses: 32,768 − 2. This traditional rule does not apply to /31 point-to-point links or /32 host routes.'},
{id:'partial-octet',ch:4,display:'01001001.00000101.<mark>0</mark>0000000.00000000 /17',q:'What is the highlighted bit?',answer:'The last network-prefix bit',options:['The last network-prefix bit','The first host bit','The last host bit','The first network-prefix bit'],explain:'Two complete octets give 16 network bits. /17 includes just the first bit of the third octet; the remaining 15 bits are host bits.'},
{id:'host-binary',ch:4,display:'01001001.00000101.0<mark>0000000.00000000</mark> /17',q:'What is highlighted?',answer:'The 15 host bits',options:['The 15 host bits','The 17 network bits','The 16 host bits','The complete 32-bit address'],explain:'The prefix ends after the first bit of the third octet. All host bits are zero here, so this is the network address.'},
{id:'mask',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'Which subnet mask corresponds to /17?',answer:'255.255.128.0',options:['255.255.128.0','255.255.0.0','255.255.255.0','255.255.192.0'],explain:'17 ones followed by 15 zeros: 11111111.11111111.10000000.00000000.'},
{id:'broadcast',ch:4,display:'73.5.0.0<mark>/17</mark>',q:'What is this subnet’s broadcast address?',answer:'73.5.127.255',options:['73.5.127.255','73.5.255.255','73.5.0.1','73.5.128.0'],explain:'Set all 15 host bits to 1. The third octet becomes 01111111 = 127, and the fourth becomes 255.'},
{id:'octet',ch:4,display:'192.168.<mark>12</mark>.34 /24',q:'How many bits does the highlighted IPv4 octet represent?',answer:'8 bits',options:['8 bits','12 bits','16 bits','4 bits'],explain:'Every IPv4 octet is 8 bits with decimal values 0–255. /24 uses the first three octets for the network.'},
{id:'host24',ch:4,display:'192.168.12.<mark>34</mark> /24',q:'What role does the highlighted octet have here?',answer:'Host portion',options:['Host portion','Part of the 24-bit network prefix','The prefix length itself','The subnet’s broadcast host value'],explain:'In /24, the first 24 bits are network bits. The final octet is the 8-bit host portion.'},
{id:'ipv6group',ch:4,display:'2001:<mark>0db8</mark>:85a3::8a2e:370:7334',q:'How many bits are represented by this IPv6 group?',answer:'16 bits',options:['16 bits','8 bits','32 bits','128 bits'],explain:'A hextet has four hexadecimal digits × 4 bits = 16 bits.'},
{id:'ipv6zero',ch:4,display:'2001:db8:85a3<mark>::</mark>8a2e:370:7334',q:'How many zero groups are compressed here?',answer:'2 groups',options:['2 groups','1 group','4 groups','6 groups'],explain:'Six explicit groups remain. IPv6 has eight groups total, so :: represents two 0000 groups here.'},
{id:'macoui',ch:3,display:'<mark>00:1A:2B</mark>:3C:4D:5E',q:'In the traditional manufacturer-assigned MAC format, what is highlighted?',answer:'24-bit OUI',options:['24-bit OUI','24-bit device identifier','16-bit OUI','The complete 48-bit MAC address'],explain:'Three hexadecimal octets = 24 bits. In the traditional universal format these identify the manufacturer allocation.'},
{id:'macdevice',ch:3,display:'00:1A:2B:<mark>3C:4D:5E</mark>',q:'What is this portion in the traditional MAC format?',answer:'24-bit interface identifier',options:['24-bit interface identifier','24-bit manufacturer OUI','16-bit interface identifier','The complete 48-bit MAC address'],explain:'The last 24 bits distinguish interfaces within the manufacturer’s allocation.'},
{id:'framebytes',ch:3,display:'14 + <mark>1500</mark> + 4 = 1518 bytes',q:'What does the highlighted number represent?',answer:'Maximum ordinary Ethernet payload',options:['Maximum ordinary Ethernet payload','Complete ordinary frame including header and FCS','Frame size including preamble but excluding FCS','Combined header and FCS overhead'],explain:'14-byte header + 1500-byte payload + 4-byte FCS = 1518-byte ordinary untagged frame. Preamble/SFD is an additional 8 bytes.'},
{id:'labels10',ch:4,display:'2<sup><mark>10</mark></sup> = 1024',q:'What does the exponent represent?',answer:'Number of bits in each label',options:['Number of bits in each label','Number of distinct labels available','Number of bytes in each label','Number of reserved labels'],explain:'n bits can label 2^n unique objects. 10 bits gives 1024 combinations.'},
{id:'labels200',ch:4,display:'<mark>200</mark> objects',q:'What is the minimum number of binary bits needed for unique labels?',answer:'8 bits',options:['8 bits','7 bits','10 bits','200 bits'],explain:'2^7 = 128 is too few; 2^8 = 256 is enough.'}
]}
let numbersChapter=0;
function numbersHome(){$('#app').innerHTML=`<div class="heading"><div><div class="eyebrow">CIS 320 / TEST 01</div><h1>Make the numbers make sense.</h1><p class="muted">Decode the highlighted part, then practice the calculation behind it.</p></div><label class="tiny">Address drill chapter <select id="numbers-chapter"><option value="0">Chapters 3 &amp; 4</option>${DATA.chapters.filter(c=>[3,4].includes(c.id)).map(c=>`<option value="${c.id}" ${numbersChapter===c.id?'selected':''}>${c.id} · ${c.title}</option>`).join('')}</select></label></div>`+`<div class="grid"><section class="card"><h2>Address detective</h2><div class="number">73.5.0.0<mark>/17</mark></div><p>CIDR, subnet masks, IPv4/IPv6, MAC addresses, frame sizes and label capacity.</p><button id="addressstart" class="primary">Decode highlighted parts</button></section><section class="card"><h2>Binary ↔ decimal ↔ hex</h2><div class="number">1010 <span class="muted">⇄</span> A</div><p>Fresh conversion problems in all four directions. Choose an answer and see the calculation step by step.</p><button id="convertstart" class="primary">Practice conversions</button></section></div><div class="notice">Address drills use the Chapters 3–4 selector above, independently of your other study sections. Conversion practice belongs to Chapter 3.</div>`;$('#numbers-chapter').onchange=e=>{numbersChapter=+e.target.value};$('#addressstart').onclick=()=>{let items=labItems().filter(x=>!numbersChapter||x.ch===numbersChapter);lab={items:shuffle(items),index:0,right:0};renderLab()};$('#convertstart').onclick=()=>{lab={conversion:true,index:0,right:0};newConversion()}}
function renderLab(){if(lab.index>=lab.items.length){$('#app').innerHTML=`<section class="card empty"><h1>Numbers decoded.</h1><p>${lab.right} / ${lab.items.length} correct</p><button id="labdone">Back to numbers lab</button></section>`;$('#labdone').onclick=()=>navigate('numbers');return}let x=lab.items[lab.index];$('#app').innerHTML=`<div class="study"><button id="backlab">← Numbers lab</button><h1>Address detective</h1><p>${chapterTitle(x.ch)} · ${lab.index+1} / ${lab.items.length}</p><div class="number">${x.display}</div>${preTeachHTML(x)}<h2 class="question" style="margin-top:24px">${x.q}</h2><div class="choices">${shuffle(x.options).map(a=>`<button data-lab="${esc(a)}">${esc(a)}</button>`).join('')}</div><div id="labfeedback" aria-live="polite"></div></div>`;$('#backlab').onclick=()=>navigate('numbers');document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{let ok=b.dataset.lab===x.answer;if(ok)lab.right++;record({id:'lab-'+x.id},ok);document.querySelectorAll('[data-lab]').forEach(v=>{v.disabled=true;if(v.dataset.lab===x.answer)v.classList.add('correct')});if(!ok)b.classList.add('wrong');$('#labfeedback').innerHTML=`${explanationHTML(x,b.dataset.lab)}<button id="labnext" class="primary">Continue →</button>`;$('#labnext').onclick=()=>{lab.index++;renderLab()}})}
function newConversion(){let n=Math.floor(Math.random()*256),types=[['binary','decimal'],['decimal','binary'],['binary','hexadecimal'],['hexadecimal','binary']],t=types[lab.index%4];const format=(v,base)=>base==='binary'?v.toString(2).padStart(8,'0'):base==='hexadecimal'?v.toString(16).toUpperCase().padStart(2,'0'):String(v);let values=[n];for(let offset of [1,-1,16,8,2]){let v=(n+offset+256)%256;if(!values.includes(v))values.push(v);if(values.length===4)break}let opts=shuffle(values),answered=false;$('#app').innerHTML=`<div class="study"><button id="backlab">← Numbers lab</button><h1>Convert ${t[0]} → ${t[1]}</h1>${preTeachHTML({ch:3,lessonId:'notes-3-4'})}<p>Chapter 3 · ${lab.right} correct of ${lab.index} completed</p><div class="number">${format(n,t[0])}</div><section class="card" style="margin-top:20px"><h2>Choose the ${t[1]} equivalent</h2><div class="choices">${opts.map(v=>`<button data-conversion="${v}">${format(v,t[1])}</button>`).join('')}</div><div id="conversionfeedback" aria-live="polite"></div></section><p class="tiny muted">Binary place values: 128 · 64 · 32 · 16 · 8 · 4 · 2 · 1. One hexadecimal digit represents four bits.</p></div>`;$('#backlab').onclick=()=>navigate('numbers');document.querySelectorAll('[data-conversion]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;let ok=+b.dataset.conversion===n;record({id:'conv-'+t[0]+'-'+t[1]},ok);lab.index++;if(ok)lab.right++;document.querySelectorAll('[data-conversion]').forEach(v=>{v.disabled=true;if(+v.dataset.conversion===n)v.classList.add('correct');else if(v===b)v.classList.add('wrong')});let bits=format(n,'binary'),hex=format(n,'hexadecimal');$('#conversionfeedback').innerHTML=`<div class="feedback"><strong>${ok?'✓ Correct — here’s why':'Not quite — here’s how to work it out'}</strong><p>The answer is <b>${format(n,t[1])}</b>.</p>${ok?'':'<p>Remember: Each binary position has a value. Add the values where you see a 1. For hexadecimal, work with four bits at a time.</p>'}<p>${bits}₂ = ${n}₁₀ = ${hex}₁₆</p><p>For decimal, add the place values where the binary digit is 1: ${[128,64,32,16,8,4,2,1].filter(v=>n&v).join(' + ')||'0'} = ${n}.</p><p>For hexadecimal, split into four-bit groups: ${bits.slice(0,4)} = ${hex[0]} and ${bits.slice(4)} = ${hex[1]}. That gives ${hex}.</p></div><button id="moreconversion" class="primary">Next conversion →</button>`;$('#moreconversion').onclick=newConversion})}
const ORDER_EXPLANATIONS={osi:'From top to bottom: services for applications, data representation, session management, end-to-end transport, routing, local frames, then physical signals. The mnemonic is All People Seem To Need Data Processing.',tcpip:'Start with the application’s data. Transport handles process-to-process delivery, Network/IP routes across networks, Data Link delivers a local frame, and Physical sends its bits as signals.',encap:'Each lower layer wraps the data from the layer above. Application data becomes a transport segment, then an IP packet, then a local frame, and finally signals on the medium.',csma:'A device listens before sending. If a collision occurs, it stops and signals the collision, waits a random interval so the devices do not retry together, then starts the sensing process again.',frame:'Synchronization and the start marker come before the frame addresses. The receiver then reads destination, source and type/length, followed by data. FCS comes last to check for corruption.',campus:'The core is the fast backbone. Distribution aggregates access networks and applies routing/policy. Access is closest to the end user and supplies device connections.',design:'First discover the needs, then plan the logical organization. Choose physical equipment to implement that plan, deploy and test it, and maintain the operating network.'};

const LEARN_TERMS=new Set(`Layering|TCP/IP|Application layer|Transport layer|Network layer|Data Link layer|Physical layer|OSI|Presentation layer|Session layer|IEEE|IETF|LAN|WLAN|TCP|IP|DNS|HTTP|Interoperability|Physical medium|Copper cable|Fiber-optic cable|Wireless|UTP|Bandwidth|Noise|Cat 5e|Cat 6|Cat 6a|Cat 8|Total internal reflection|Core|Single-mode fiber|Multimode fiber|Amplitude|Frequency|Phase|Modulation|AM|FM|PM|QAM|Multiplexing|FDM|TDM|Ethernet|Frame|Packet|Payload|NIC|MAC|OUI|Broadcast|CSMA/CD|Collision|Backoff|Preamble|SFD|Destination MAC|Source MAC|EtherType|Padding|FCS|Bit|Byte|Binary|Decimal|Hexadecimal|Hub|Switch|STP|Topology|Star topology|Bus topology|Ring topology|Mesh topology|Router|Routing|Routing table|Next hop|IPv4|IPv6|Network portion|Host portion|CIDR|Prefix length|Network address|Broadcast address|Classful addressing|Zero compression|ICMP|Ping|Traceroute|Pathping|Latency|Packet loss|RIR|Requirements analysis|Logical design|Physical design|Building network|Structured cabling|Horizontal cabling|Vertical cabling|Telecommunications room|Data center|Data center topology|Campus network|Core layer|Distribution layer|Access layer|Backbone|Enterprise network|WAN|ISP|Firewall|Authentication|Network maintenance|Downtime|SNMP|MIB|Polling|Standard|Working group`.split('|'));
function learnPool(){return [...DATA.questions.map(x=>({...x,kind:'guide'})),...VOCAB.filter(x=>LEARN_TERMS.has(x.term)).map(x=>({...x,kind:x.exp?'abbreviation':'term'})),...clozeCards(),...wordBankCards(VOCAB.filter(x=>LEARN_TERMS.has(x.term))),...ORDERS.filter(x=>['osi','tcpip','csma','frame','campus'].includes(x.id)).map(x=>({...x,id:'sort-'+x.id,orderId:x.id,kind:'sort',q:x.title,explain:ORDER_EXPLANATIONS[x.id]})),...labItems().map(x=>({...x,id:'lab-'+x.id,kind:'number',note:'Study-guide number practice'})),...conversionCards()]}
function conversionCards(){return [
{id:'mixed-bin-dec',ch:3,kind:'number',q:'What decimal value does the highlighted binary group represent?',display:'<mark>00001010</mark>₂',answer:'10',options:['10','8','12','1010'],explain:'The 1s occupy the 8 and 2 positions: 8 + 2 = 10.',sourceId:'q151'},
{id:'mixed-dec-bin',ch:3,kind:'number',q:'Which binary number represents the highlighted decimal value?',display:'<mark>13</mark>₁₀',answer:'00001101',options:['00001101','00001011','00001110','00000111'],explain:'13 = 8 + 4 + 1. Put 1s in those three positions to obtain 00001101.',sourceId:'q151'},
{id:'mixed-bin-hex',ch:3,kind:'number',q:'Which hexadecimal digit represents the highlighted four bits?',display:'1010 <mark>1111</mark>₂',answer:'F',options:['F','E','A','B'],explain:'1111 = 8 + 4 + 2 + 1 = 15. The hexadecimal digit for 15 is F.',sourceId:'q151'},
{id:'mixed-hex-bin',ch:3,kind:'number',q:'Which four binary bits represent the highlighted hex digit?',display:'<mark>A</mark>F₁₆',answer:'1010',options:['1010','1111','1001','1100'],explain:'Hexadecimal A is decimal 10. Since 10 = 8 + 2, its binary representation is 1010.',sourceId:'q151'}]}
function mixedReview(pool){let selected=[];for(const kind of ['guide','term','abbreviation','wordbank','sort','number']){const candidates=pool.filter(x=>x.kind===kind);if(candidates.length)selected.push(reviewPool(candidates)[0])}const remaining=reviewPool(pool.filter(x=>!selected.some(y=>y.id===x.id)));return shuffle([...selected,...remaining.slice(0,10-selected.length)])}
const lastOrders=new Map();
function shuffledOrder(items){
 const key=JSON.stringify(items),previous=lastOrders.get(key),same=(a,b)=>JSON.stringify(a)===b;
 let result=shuffle(items);
 for(let i=0;i<24&&(same(result,key)||same(result,previous));i++)result=shuffle(items);
 // Deterministic fallback also works when the random generator repeats itself.
 if(same(result,key)||same(result,previous)){
   outer:for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){
     const candidate=[...items];[candidate[i],candidate[j]]=[candidate[j],candidate[i]];
     if(!same(candidate,key)&&!same(candidate,previous)){result=candidate;break outer}
   }
 }
 if(same(result,key)&&items.length>1)result=[...items.slice(1),items[0]];
 lastOrders.set(key,JSON.stringify(result));return result;
}
function clozeCards(){
 const rows=[
 [1,'____ develops LAN/WLAN standards; ____ develops Internet protocol standards.',['IEEE','IETF'],['ISO','RIR'],'IEEE develops standards such as Ethernet and Wi-Fi. IETF develops Internet protocol standards such as TCP/IP and DNS.',true],
 [1,'The ____ layer handles IP routing; the ____ layer handles local frames and MAC addresses.',['Network','Data Link'],['Transport','Physical'],'Network routes packets between networks using IP addresses. Data Link handles delivery of frames over a local link.'],
 [1,'The ____ layer represents bits as signals; the ____ layer provides end-to-end communication between application processes.',['Physical','Transport'],['Network','Application'],'Physical sends the electrical, light or radio signals. Transport handles communication between the application processes at the endpoints.'],
 [1,'In OSI, the ____ layer formats, encrypts and compresses data; the ____ layer manages communication sessions.',['Presentation','Session'],['Application','Transport'],'Presentation handles data representation. Session starts, manages and ends sessions.'],
 [1,'OSI has ____ layers; the TCP/IP model in this study guide has ____ layers.',['seven','five'],['four','six'],'Your course uses seven OSI layers and the five-layer TCP/IP teaching model. Use that five-layer version for these exercises.'],
 [1,'Layering divides communication into separate ____ so one part can change without redesigning everything.',['responsibilities'],['manufacturers','addresses','cables'],'Each layer has a defined job and interface, which makes changes and troubleshooting more manageable.'],
 [2,'Copper carries ____ signals; optical fiber carries ____ signals.',['electrical','light'],['radio','sound'],'The physical medium determines how the signal travels: electrical signals through copper and light through fiber.'],
 [2,'UTP stands for Unshielded ____ Pair.',['Twisted'],['Transmission','Transport','Terminal'],'Twisting the copper pairs helps reduce interference. UTP has no shielding.',true],
 [2,'____ fiber is generally preferred for longer links; ____ fiber is generally used for shorter building or data-center links.',['Single-mode','Multimode'],['Copper','Wireless'],'Single-mode has a smaller core and limits light paths. Multimode has a larger core and multiple paths. Actual reach depends on the fiber and optics.'],
 [2,'AM varies ____; FM varies ____; PM varies ____.',['amplitude','frequency','phase'],[],'These names identify the signal property that changes to carry information: amplitude, frequency or phase.',true],
 [2,'FDM separates channels by ____; TDM separates them into ____.',['frequency bands','time slots'],['IP addresses','cable categories'],'FDM uses different frequency ranges. TDM gives each channel a turn in time.',true],
 [2,'Total internal ____ keeps light guided inside an optical fiber’s core.',['reflection'],['absorption','interference','routing'],'At the appropriate angle, light reflects back into the core instead of escaping into the cladding.'],
 [3,'An Ethernet frame’s ____ checks for corruption; its ____ is the carried data.',['FCS','payload'],['OUI','preamble'],'FCS is the frame check sequence at the end of a frame. The payload is the data the frame carries.'],
 [3,'In a traditional manufacturer-assigned MAC address, the first 24 bits are the ____ and the last 24 bits distinguish the ____.',['OUI','interface'],['IP prefix','subnet mask'],'The OUI identifies the manufacturer allocation. The remaining bits distinguish interfaces within it.'],
 [3,'After a collision, CSMA/CD uses a ____ delay before trying again.',['random backoff'],['fixed routing','zero-length','DNS lookup'],'Random waiting helps prevent devices that collided from retrying at exactly the same time.',true],
 [3,'One byte contains ____ bits; one hexadecimal digit represents ____ bits.',['eight','four'],['two','sixteen'],'A byte is eight bits. A hexadecimal digit has 16 possible values, so four binary bits can represent one hex digit.'],
 [3,'A ____ topology connects devices to a central device; a ____ topology uses one shared backbone cable.',['star','bus'],['ring','mesh'],'The central connection is the defining feature of star. A shared cable is the defining feature of bus.'],
 [4,'In IPv4 /17, ____ bits identify the network and ____ bits remain for hosts.',['17','15'],['16','32'],'IPv4 has 32 bits. The prefix uses 17, leaving 32 − 17 = 15 host bits.'],
 [4,'An IPv4 address contains ____ bits; an IPv6 address contains ____ bits.',['32','128'],['64','16'],'IPv4 uses four 8-bit octets. IPv6 uses eight 16-bit groups.'],
 [4,'The ____ address has all host bits set to zero; the ____ address has all host bits set to one in a traditional IPv4 subnet.',['network','broadcast'],['next-hop','MAC'],'The network address identifies the subnet. The broadcast address targets the subnet’s hosts under traditional IPv4 subnet rules.'],
 [4,'____ checks for echo replies; ____ shows successive hops along a path.',['Ping','Traceroute'],['SNMP','DNS'],'Ping tests reachability using echo requests and replies. Traceroute reveals routers along the path using probes with increasing hop limits.'],
 [12,'The campus ____ layer connects end devices; ____ aggregates access networks; ____ provides the fast backbone.',['Access','Distribution','Core'],[],'Access is closest to users. Distribution groups access networks and applies policy. Core carries traffic between major parts of the campus.'],
 [12,'____ design plans the network’s organization and addressing; ____ design chooses equipment and media.',['Logical','Physical'],['Application','Session'],'Logical design describes how the network is organized. Physical design selects devices and cabling to implement that plan.'],
 [12,'____ cabling serves work areas on a floor; ____ cabling connects floors or telecommunications rooms.',['Horizontal','Vertical/backbone'],['Application','Transport'],'Horizontal runs go to work areas. Vertical or backbone runs join telecommunications spaces.'],
 [12,'SNMP managers query device ____; a ____ describes the managed information.',['agents','MIB'],['payload','subnet'],'Agents expose management information on devices. The management information base defines the objects the manager can query.',true]
 ];
 return rows.map(([ch,q,tokens,extras,explain,abbrev],i)=>({id:'cloze-'+i,ch,q,kind:'wordbank',cloze:true,tokens,extras,answer:tokens.join(' '),explain,abbrev,note:'Study-guide sentence practice'}));
}
function wordBankCards(list){return list.filter(x=>x.exp&&x.exp.trim().split(/\s+/).length>1).map(x=>({...x,id:'build-'+x.id,kind:'wordbank',q:`Build the full name of ${x.term}.`,answer:x.exp,explain:`${x.term} stands for ${x.exp}.\n${x.a}`}))}
function prepareWordBank(x){return {...x,words:x.tokens||x.exp.trim().split(/\s+/),bank:shuffledOrder([...(x.tokens||x.exp.trim().split(/\s+/)),...(x.extras||[])]),picked:[]}}
function wordBankAnswer(x){return x.picked.map(i=>x.bank[i]).join(' ')}
function renderWordBank(x){
 const s=session,full=x.picked.length===x.words.length,ok=wordBankAnswer(x)===x.words.join(' ');
 $('#app').innerHTML=`<div class="study"><div class="row spread"><button id="exit">← Exit session</button><span>${sessionStatus(s)}</span></div><div class="bar" style="margin:24px 0"><span style="width:${100*s.cleared.size/s.total}%"></span></div><span class="tag">${questionContext(x)}</span>${preTeachHTML(x)}<section class="card" style="margin-top:16px"><div class="eyebrow">${x.cloze?'COMPLETE THE SENTENCE':'BUILD THE ABBREVIATION'}</div><h2 class="question">${x.cloze?x.q.split('____').map((part,i)=>esc(part)+(i<x.words.length?`<mark class="blank">${x.picked[i]===undefined?'____':esc(x.bank[x.picked[i]])}</mark>`:'')).join(''):esc(x.q)}</h2><p>${x.cloze?'Fill the blanks from left to right. Extra choices may remain.':'Tap the words in order.'} Tap a chosen word to put it back.</p><div class="word-answer" aria-label="Your assembled answer">${x.picked.length?x.picked.map((i,pos)=>`<button data-unpick="${pos}" ${s.revealed?'disabled':''} aria-label="Remove word ${pos+1}: ${esc(x.bank[i])}">${esc(x.bank[i])}</button>`).join(''):'<span class="muted">Your answer goes here</span>'}</div><div class="word-bank" aria-label="Available words">${x.bank.map((word,i)=>`<button data-pick="${i}" ${s.revealed||full||x.picked.includes(i)?'disabled':''}>${esc(word)}</button>`).join('')}</div><div class="actions"><button id="word-check" class="primary" ${!full||s.revealed?'disabled':''}>Check answer</button><button id="word-clear" ${!x.picked.length||s.revealed?'disabled':''}>Clear answer</button></div>${s.revealed?explanationHTML(x,wordBankAnswer(x))+retryNotice(ok)+'<button id="continue" class="primary">Continue →</button>':''}</section></div>`;
 $('#exit').onclick=()=>navigate(view);
 document.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{const i=+b.dataset.pick;if(!s.revealed&&!full&&!x.picked.includes(i)){x.picked.push(i);renderWordBank(x)}});
 document.querySelectorAll('[data-unpick]').forEach(b=>b.onclick=()=>{if(!s.revealed){x.picked.splice(+b.dataset.unpick,1);renderWordBank(x)}});
 $('#word-clear').onclick=()=>{if(!s.revealed){x.picked=[];renderWordBank(x)}};
 $('#word-check').onclick=()=>{if(full&&!s.revealed){s.revealed=true;renderWordBank(x)}};
 if($('#continue'))$('#continue').onclick=()=>advance(ok);
}
function understandingHome(){let pool=chosen(DATA.understanding),seen=pool.filter(x=>progress.cards[x.id]?.seen).length;$('#app').innerHTML=heading('Check your understanding','New situations and close comparisons, using only the topics in your study guide.')+`<section class="card"><div class="eyebrow">SEPARATE PRACTICE BANK</div><h2>Apply what you’ve learned</h2><p>${pool.length} questions · ${seen} tried · ${pool.filter(mastered).length} retained</p><p>Every question links back to an original guide prompt. These are practice questions based on the guide, not predictions of the actual exam.</p><div class="actions"><button class="primary" id="understand-ten">Practice 10</button><button id="understand-all">Practice all ${pool.length}</button></div></section><div class="grid" style="margin-top:24px">${DATA.chapters.filter(c=>!chapter||c.id===chapter).map(c=>`<article class="card"><span class="tag">Chapter ${c.id}</span><h3>${c.title}</h3><p>${DATA.understanding.filter(x=>x.ch===c.id).length} applied questions, each tied to the guide.</p><button data-understand="${c.id}">Check this chapter →</button></article>`).join('')}</div>`;$('#understand-ten').onclick=()=>start('understanding',reviewPool(pool));$('#understand-all').onclick=()=>start('understanding',shuffle(pool));document.querySelectorAll('[data-understand]').forEach(b=>b.onclick=()=>{chapter=+b.dataset.understand;start('understanding',shuffle(chosen(DATA.understanding)))})}
function renderMixedSort(x){let s=session;$('#app').innerHTML=`<div class="study"><div class="row spread"><button id="exit">← Exit session</button><span>${sessionStatus(s)}</span></div><div class="bar" style="margin:24px 0"><span style="width:${100*s.cleared.size/s.total}%"></span></div><span class="tag">${questionContext(x)}</span>${preTeachHTML(x)}<section class="card" style="margin-top:16px"><div class="eyebrow">PUT IT IN ORDER</div><h2>${esc(x.title)}</h2><p>${esc(x.instruction)}</p><div class="order">${x.current.map((t,i)=>`<div><strong>${i+1}</strong><span>${esc(t)}</span><button data-move="${i}" data-dir="-1" aria-label="Move ${esc(t)} up" ${i===0||s.revealed?'disabled':''}>↑</button><button data-move="${i}" data-dir="1" aria-label="Move ${esc(t)} down" ${i===x.current.length-1||s.revealed?'disabled':''}>↓</button></div>`).join('')}</div><button class="primary" id="check-mixed-sort" ${s.revealed?'disabled':''}>Check order</button><div id="sort-explanation"></div></section></div>`;$('#exit').onclick=()=>navigate(view);document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{if(s.revealed)return;let i=+b.dataset.move,j=i+(+b.dataset.dir);[x.current[i],x.current[j]]=[x.current[j],x.current[i]];renderMixedSort(x)});$('#check-mixed-sort').onclick=()=>{if(s.revealed)return;let ok=x.current.every((v,i)=>v===x.items[i]);s.revealed=true;renderMixedSort(x);$('#sort-explanation').innerHTML=`<div class="feedback" role="status"><strong>${ok?'✓ Correct — here’s why':'Not quite — here is the correct order'}</strong><ol class="answer-steps">${x.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="explanation">${readableText(ok?x.explain:beginnerReminder(x))}</div>${retryNotice(ok)}</div><button id="continue" class="primary">Continue →</button>`;$('#continue').onclick=()=>advance(ok)}}

